### Full minimal example (ES-module import)

```js
import * as maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';

const map = new maplibregl.Map({
  container: 'map',
  style: 'https://tiles.openfreemap.org/styles/liberty', // any non-Mapbox style
  center: [-122.42, 37.78],
  zoom: 12
});

async function addPin(url) {
  const { data: img } = await map.loadImage(url);   // ← promise version
  // `img` is an ImageBitmap (or HTMLImageElement) that MapLibre can use
  map.addImage('pin', img);
}

map.on('load', () => {
  // add the custom icon once the style is ready
  addPin('https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/pin.png')
    .catch(console.error);

  // now you can use the icon in a layer, e.g.:
  map.addLayer({
    id: 'my-pins',
    type: 'symbol',
    source: {
      type: 'geojson',
      data: {
        type: 'FeatureCollection',
        features: [{
          type: 'Feature',
          geometry: { type: 'Point', coordinates: [-122.42, 37.78] },
          properties: {}
        }]
      }
    },
    layout: {
      'icon-image': 'pin',
      'icon-size': 0.8
    }
  });
});
```

