## Full minimal example (MapLibre v6)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre marker-icon migration</title>
  <link href="https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty', // any non-Mapbox style
    center: [-122.42, 37.78],
    zoom: 12
  });

  map.on('load', async () => {
    // ---- load the custom icon ----
    try {
      const { data } = await map.loadImage('https://raw.githubusercontent.com/mapbox/mapbox-gl-js/main/docs/assets/custom_marker.png');
      map.addImage('pin', data);
    } catch (e) {
      console.error('Icon load failed', e);
    }

    // ---- add a layer that uses the icon ----
    map.addLayer({
      id: 'my-pins',
      type: 'symbol',
      source: {
        type: 'geojson',
        data: {
          type: 'FeatureCollection',
          features: [{
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [-122.42, 37.78] },
            properties: {}
          }]
        }
      },
      layout: {
        'icon-image': 'pin',   // <-- matches the name we added above
        'icon-size': 0.8
      }
    });
  });
</script>
</body>
</html>
```

Run this in a browser (or your dev server). The custom pin appears, proving the promise-based `loadImage` works.

