## Full minimal example

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre – custom marker image</title>
  <link href="https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty', // any non-Mapbox style
    center: [-122.42, 37.78],
    zoom: 12
  });

  // Wait for the style to be ready
  map.on('load', async () => {
    try {
      const { data: img } = await map.loadImage(
        'https://raw.githubusercontent.com/mapbox/mapbox-gl-js/main/docs/assets/custom_marker.png'
      );
      map.addImage('pin', img);

      // Now add a layer that uses the image
      map.addLayer({
        id: 'my-marker',
        type: 'symbol',
        source: {
          type: 'geojson',
          data: {
            type: 'FeatureCollection',
            features: [{
              type: 'Feature',
              geometry: { type: 'Point', coordinates: [-122.42, 37.78] },
              properties: {}
            }]
          }
        },
        layout: {
          'icon-image': 'pin',
          'icon-size': 0.5
        }
      });
    } catch (e) {
      console.error('Could not load custom marker image', e);
    }
  });
</script>
</body>
</html>
```

